library(tidyverse)


data("billboard", package = "tidyr")

billboard_long &lt;- billboard |&gt;
  pivot_longer(
    cols = starts_with("wk"),
    names_to = "week",
    names_prefix = "wk",
    values_to = "rank"
  ) |&gt;
  filter(!is.na(rank)) |&gt;
  mutate(week = as.integer(week))

top_tracks &lt;- billboard_long |&gt;
  count(track, artist, name = "weeks_on_chart") |&gt;
  slice_max(weeks_on_chart, n = 8, with_ties = FALSE) |&gt;
  mutate(song = paste(track, artist, sep = " — "))

billboard_top &lt;- billboard_long |&gt;
  semi_join(top_tracks, by = c("track", "artist")) |&gt;
  mutate(song = paste(track, artist, sep = " — "))

ggplot(billboard_top, aes(x = week, y = rank)) +
  geom_line(color = "#287271", linewidth = 1) +
  geom_point(
    data = \(data) filter(data, rank == 1),
    color = "#E76F51",
    size = 2.5
  ) +
  facet_wrap(vars(song), ncol = 2) +
  scale_y_reverse(breaks = seq(10, 100, by = 10)) +
  labs(
    title = "The Long Haul: Billboard Hot 100",
    subtitle = "Weekly rank for the eight longest-charting songs in the dataset",
    x = "Week on the chart",
    y = "Billboard rank (1 = highest)",
    caption = "Each line follows one song; orange dots mark weeks it reached No. 1."
  ) +
  theme_minimal(base_size = 12) +
  theme(
    plot.title = element_text(face = "bold"),
    strip.text = element_text(face = "bold"),
    panel.grid.minor = element_blank()
  )
